#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 100005

typedef long long ll;

struct Edge {
    int to, next;
    ll w;
} edges[MAXN * 2];

int head[MAXN], cnt;
ll dist[MAXN];
int visited[MAXN];
int n, q, k;

void add_edge(int u, int v, ll w) {
    edges[cnt].to = v;
    edges[cnt].w = w;
    edges[cnt].next = head[u];
    head[u] = cnt++;
}

// Iterative DFS
void dfs(int start) {
    int stack[MAXN];
    int top = 0;
    stack[top++] = start;
    dist[start] = 0;
    visited[start] = 1;

    while (top > 0) {
        int u = stack[--top];
        for (int i = head[u]; i != -1; i = edges[i].next) {
            int v = edges[i].to;
            ll w = edges[i].w;
            if (!visited[v]) {
                visited[v] = 1;
                dist[v] = dist[u] + w;
                stack[top++] = v;
            }
        }
    }
}

int main() {
    scanf("%d %d %d", &n, &q, &k);

