        ll w;
        scanf("%d %d %lld", &u, &v, &w);
        add_edge(u, v, w);
        add_edge(v, u, w);
    }

    memset(visited, 0, sizeof(visited));
    memset(dist, 0, sizeof(dist));

    dfs(k);

    for (int i = 0; i < q; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        printf("%lld\n", dist[x] + dist[y]);
    }

    return 0;
}

