typedef struct Edge {
    int to, len;
    struct Edge *next;
} Edge;

Edge *adj[MAXN];
long long dist[MAXN];

void add_edge(int u, int v, int w) {
    Edge *e = (Edge*)malloc(sizeof(Edge));
    e->to = v;
    e->len = w;
    e->next = adj[u];
    adj[u] = e;
}

void dfs(int u, int parent) {
    for (Edge *e = adj[u]; e; e = e->next) {
        int v = e->to;
        if (v == parent) continue;
        dist[v] = dist[u] + e->len;
        dfs(v, u);
    }
}

