#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct Edge {
    int to;
    ll w;
    int next;
} Edge;

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int M = 2 * (N - 1);
    Edge *edges = (Edge *)malloc(sizeof(Edge) * M);
    int *head = (int *)malloc(sizeof(int) * (N + 1));
    for (int i = 1; i <= N; i++) head[i] = -1;

    int edge_cnt = 0;
    for (int i = 0; i < N - 1; i++) {
        int a, b;
        ll c;
        scanf("%d %d %lld", &a, &b, &c);

        edges[edge_cnt].to = b;
        edges[edge_cnt].w = c;
        edges[edge_cnt].next = head[a];
        head[a] = edge_cnt++;

        edges[edge_cnt].to = a;
        edges[edge_cnt].w = c;
        edges[edge_cnt].next = head[b];
        head[b] = edge_cnt++;
    }

    int Q, K;
    scanf("%d %d", &Q, &K);

    ll *dist = (ll *)malloc(sizeof(ll) * (N + 1));
    int *stack = (int *)malloc(sizeof(int) * N);
    int *parent = (int *)malloc(sizeof(int) * (N + 1));

    for (int i = 1; i <= N; i++) {
        dist[i] = -1;
        parent[i] = 0;
    }

    int top = 0;
    stack[top++] = K;
    dist[K] = 0;
    parent[K] = -1;

    while (top > 0) {
        int v = stack[--top];
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            if (to == parent[v]) continue;
            parent[to] = v;
            dist[to] = dist[v] + edges[e].w;
            stack[top++] = to;
        }
    }

    for (int i = 0; i < Q; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        printf("%lld\n", dist[x] + dist[y]);
    }

    free(edges);
    free(head);
    free(dist);
    free(stack);
    free(parent);

    return 0;
}

